{
  "name": "AMI 持久模式超导磁体线圈",
  "name_en": "AMI Persistent-Mode Superconducting Magnet Coil",
  "manufacturer": "American Magnetics, Inc.",
  "description": "这是一种带持久开关加热器的超导磁体线圈，可由 AMI 磁体电源励磁，并在持久模式下维持稳定磁场。它常用于低温物理、量子器件和精密电学实验中，为样品提供稳定的直流磁场偏置。",
  "description_en": "A superconducting magnet coil with a persistent switch heater, intended to be energized by an AMI magnet power supply and then operated in persistent mode to maintain a stable magnetic field. It is commonly used in low-temperature physics, quantum-device experiments, and precision electrical measurements to provide a stable DC magnetic bias field.",
  "tag_hints": [
    "superconducting magnet",
    "persistent mode",
    "magnet power supply",
    "persistent switch heater",
    "quench detection",
    "magnetic field bias",
    "cryogenic experiments"
  ],
  "actions": [
    {
      "action_name": "auto-get_all",
      "description": "读取线圈及持久开关的全部可用状态信息。",
      "description_en": "Read all available status information of the coil and persistent switch."
    },
    {
      "action_name": "auto-check_for_quench",
      "description": "检查超导线圈是否发生失超。",
      "description_en": "Check whether the superconducting coil is in a quench state."
    },
    {
      "action_name": "auto-set_source_field",
      "description": "设置电源侧目标磁场。",
      "description_en": "Set the target field on the power-supply side."
    },
    {
      "action_name": "auto-get_source_field",
      "description": "获取电源侧磁场设定值或当前值。",
      "description_en": "Get the field setpoint or current value on the power-supply side."
    },
    {
      "action_name": "auto-heater_enabled",
      "description": "获取持久开关加热器是否开启。",
      "description_en": "Get whether the persistent switch heater is enabled."
    },
    {
      "action_name": "auto-turn_on_heater",
      "description": "开启或关闭持久开关加热器。",
      "description_en": "Turn the persistent switch heater on or off."
    },
    {
      "action_name": "auto-get_switch_state",
      "description": "获取持久开关状态。",
      "description_en": "Get the state of the persistent switch."
    },
    {
      "action_name": "auto-set_switch_state",
      "description": "设置持久开关状态，在超导态与常导态之间切换。",
      "description_en": "Set the persistent switch state, switching between superconducting and normal-conducting states."
    },
    {
      "action_name": "auto-set_field",
      "description": "设置线圈的目标磁场。",
      "description_en": "Set the target magnetic field of the coil."
    },
    {
      "action_name": "auto-get_field",
      "description": "获取线圈的持久磁场。",
      "description_en": "Get the persistent magnetic field of the coil."
    },
    {
      "action_name": "auto-field_to_curr",
      "description": "将线圈磁场值换算为对应电流。",
      "description_en": "Convert a coil magnetic field value to the corresponding current."
    },
    {
      "action_name": "auto-curr_to_field",
      "description": "将线圈电流值换算为对应磁场。",
      "description_en": "Convert a coil current value to the corresponding magnetic field."
    },
    {
      "action_name": "auto-fake_folder",
      "description": "创建一个用于记录该线圈数据的虚拟测量文件夹。",
      "description_en": "Create a dummy measurement folder for recording data related to the coil."
    },
    {
      "action_name": "auto-compensate_for_drift",
      "description": "通过调整供电电流补偿持久模式下的磁场漂移。",
      "description_en": "Compensate field drift in persistent mode by adjusting the supplied current."
    },
    {
      "action_name": "auto-bring_source_to_field",
      "description": "将电源输出调整到与线圈当前持久磁场相匹配。",
      "description_en": "Bring the power-supply output into agreement with the coil's current persistent field."
    },
    {
      "action_name": "auto-step_field_to_value",
      "description": "以步进方式将线圈磁场缓慢扫到目标值。",
      "description_en": "Ramp the coil field to a target value in discrete steps."
    },
    {
      "action_name": "auto-measure_field",
      "description": "测量线圈产生的磁场。",
      "description_en": "Measure the magnetic field produced by the coil."
    }
  ]
}

